   669  _conv_num(const unsigned char **buf, int *dest, int llim, int ulim)
   670  {
   671          int result = 0;
   672          int rulim = ulim;
   673
   674          if (**buf < '0' || **buf > '9')
   675                  return (0);
   676
   677          /* we use rulim to break out of the loop when we run out of digits */
   678          do {
   679                  result *= 10;
   680                  result += *(*buf)++ - '0';
   681                  rulim /= 10;
   682          } while ((result * 10 <= ulim) && rulim && **buf >= '0' && **buf <= '9');
   683
   684          if (result < llim || result > ulim)
   685                  return (0);
   686
   687          *dest = result;
   688          return (1);
   689  }
